-- Waypath+ arcade (hidden): the XP you earn while levelling pays out coins, and coins buy
-- packs of five collectible cards: iconic items, NPCs and places from the world. Every card can
-- come as a common, a rare, a holo or a full-art print. Nothing here is announced; /wp arcade
-- opens it. Coins and cards are saved for the whole account (WaypathDB.arcade).
-- The card list is ArcadeCards.lua (generated by tools/arcade/gen.py).
local _, RG = ...

local KIND = { "Item", "NPC", "Place", "Legend" }
local TIER = {  -- how rare the subject itself is: draw weight, name colour
  { "Everyday", 44, { 0.8, 0.8, 0.8 } }, { "Notable", 26, { 0.3, 0.85, 0.3 } }, { "Famous", 14, { 0.3, 0.55, 1 } },
  { "Epic", 12, { 0.7, 0.35, 0.95 } }, { "Legendary", 4, { 1, 0.6, 0.1 } },
  { "Super rare", 3, { 1, 0.2, 0.35 } },   -- the Legends set
}
local FINISH = {  -- finish names, draw weights, power bonus, sell price
  { "Common", 70, 0, 1 }, { "Rare", 22, 6, 3 }, { "Holo", 6, 16, 10 }, { "Full art", 2, 30, 30 },
}
local CREATURE_ICON = {
  [1] = "Ability_Hunter_Pet_Wolf", [2] = "INV_Misc_Head_Dragon_01", [3] = "Spell_Shadow_SummonFelHunter", [4] = "Spell_Fire_Elemental_Totem",
  [5] = "Spell_Nature_EarthElemental_Totem", [6] = "Spell_Shadow_AnimateDead", [7] = "INV_Misc_Head_Orc_01", [8] = "Ability_Hunter_Pet_Rabbit",
  [9] = "INV_Gizmo_01",
}
local PACK_PRICE, PACK_SIZE = 30, 5

local CARDS = {}
for i, d in ipairs(RG.ARCADE_DATA or {}) do CARDS[i] = { id = i, kind = d[1], name = d[2], tier = d[3], ref = d[4], text = d[5] } end
-- Legends: super rare cards (holo or full art only). Names only, with no quotes or claims; the art is a game icon.
local LEGENDS = {
  { "Asmongold", "Content creator legend", "Interface\\Icons\\INV_Crown_01" },
  { "Madseasonshow", "Content creator legend", "Interface\\Icons\\Spell_Fire_Fire" },
  { "Leeroy Jenkins", "Legend of the Upper Blackrock Spire", "Interface\\Icons\\INV_Misc_Head_Dragon_01" },
  { "Xaryu", "Content creator legend", "Interface\\Icons\\INV_Crown_01" },
  { "Savvier", "Content creator legend", "Interface\\Icons\\INV_Crown_01" },
}
for _, l in ipairs(LEGENDS) do CARDS[#CARDS + 1] = { id = #CARDS + 1, kind = 4, name = l[1], tier = 6, ref = 0, text = l[2], icon = l[3] } end
RG.ARCADE_CARDS = CARDS

local function store()
  if not WaypathDB then return nil end
  local a = WaypathDB.arcade
  if not a then a = { coins = 0, cards = {}, acc = 0, packs = 0, wins = 0, losses = 0, v = 3 }; WaypathDB.arcade = a end
  if (a.v or 0) < 2 then   -- the first, creature-only set: swap each card for coins
    local n = 0
    for _, c in pairs(a.cards or {}) do if type(c) == "number" and c > 0 then n = n + 10 end end
    a.cards = {}; a.coins = (a.coins or 0) + n; a.v = 2
  end
  if a.v == 2 then   -- cards were saved by list position; keep them by name so the list can grow
    local moved = {}
    for id, slot in pairs(a.cards) do if type(id) == "number" and CARDS[id] then moved[CARDS[id].name] = slot end end
    a.cards = moved; a.v = 3
  end
  a.cards = a.cards or {}
  return a
end
local function owned(a, id) local c = a.cards[CARDS[id].name]; return c and ((c[1] or 0) + (c[2] or 0) + (c[3] or 0) + (c[4] or 0)) or 0 end
local function bestFinish(a, id) local c = a.cards[CARDS[id].name]; if not c then return nil end; for f = 4, 1, -1 do if (c[f] or 0) > 0 then return f end end end

-- ---------------------------------------------------------------------------
-- Coins from XP: 1 coin for every 2% of a level you gain
-- ---------------------------------------------------------------------------
local lastXP, lastMax
local function earn(gainPct)
  local a = store(); if not a then return end
  a.acc = (a.acc or 0) + gainPct
  local coins = math.floor(a.acc / 2)
  if coins > 0 then a.acc = a.acc - coins * 2; a.coins = (a.coins or 0) + coins end
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
end
local ev = CreateFrame("Frame")
ev:RegisterEvent("PLAYER_LOGIN"); ev:RegisterEvent("PLAYER_XP_UPDATE"); ev:RegisterEvent("PLAYER_LEVEL_UP")
ev:SetScript("OnEvent", function(_, event)
  if not (UnitXP and UnitXPMax) then return end
  local xp, max = UnitXP("player"), UnitXPMax("player")
  if not xp or not max or max <= 0 or (RG.IsSecret and (RG.IsSecret(xp) or RG.IsSecret(max))) then return end
  if event == "PLAYER_LOGIN" then lastXP, lastMax = xp, max; return end
  if event == "PLAYER_LEVEL_UP" then return end -- the XP update that follows carries the numbers
  if lastXP then
    local gain
    if xp >= lastXP then gain = xp - lastXP else gain = (lastMax or max) - lastXP + xp end
    if gain > 0 and gain < (lastMax or max) * 3 then earn(gain / max * 100) end
  end
  lastXP, lastMax = xp, max
end)

-- ---------------------------------------------------------------------------
-- Packs, selling, duels
-- ---------------------------------------------------------------------------
local byTier, tierWeight
local function buildPools()
  byTier, tierWeight = {}, 0
  for _, c in ipairs(CARDS) do byTier[c.tier] = byTier[c.tier] or {}; table.insert(byTier[c.tier], c) end
  for t = 1, #TIER do if byTier[t] then tierWeight = tierWeight + TIER[t][2] end end
end
local function rollCard()
  if not byTier then buildPools() end
  local x = math.random() * tierWeight
  local tier = 1
  for t = 1, #TIER do
    if byTier[t] then x = x - TIER[t][2]; if x <= 0 then tier = t; break end end
  end
  local pool = byTier[tier] or CARDS
  return pool[math.random(#pool)]
end
local function rollFinish(atLeast)
  local total = 0
  for f = atLeast or 1, #FINISH do total = total + FINISH[f][2] end
  local x = math.random() * total
  for f = atLeast or 1, #FINISH do x = x - FINISH[f][2]; if x <= 0 then return f end end
  return atLeast or 1
end

function RG.ArcadeOpenPack()
  local a = store(); if not a or #CARDS == 0 then return nil, "No cards loaded." end
  if (a.coins or 0) < PACK_PRICE then return nil, "A pack costs " .. PACK_PRICE .. " coins." end
  a.coins = a.coins - PACK_PRICE; a.packs = (a.packs or 0) + 1
  local got = {}
  for i = 1, PACK_SIZE do
    local c = rollCard()
    local f = rollFinish(c.tier == 6 and 3 or (i == PACK_SIZE and 2 or 1))   -- the last card of a pack is always a rare or better
    local isNew = owned(a, c.id) == 0
    local slot = a.cards[c.name] or {}
    slot[f] = (slot[f] or 0) + 1
    a.cards[c.name] = slot
    got[#got + 1] = { card = c, finish = f, new = isNew }
  end
  return got
end

-- keep one of each print, sell the rest
function RG.ArcadeSellExtras()
  local a = store(); if not a then return 0, 0 end
  local coins, cnt = 0, 0
  for id, slot in pairs(a.cards) do
    for f = 1, 4 do
      local n = slot[f] or 0
      if n > 1 then coins = coins + (n - 1) * FINISH[f][4]; cnt = cnt + n - 1; slot[f] = 1 end
    end
  end
  a.coins = (a.coins or 0) + coins
  return cnt, coins
end

local function power(c, f) return (c.tier == 6 and 5.5 or c.tier) * 18 + FINISH[f or 1][3] + (c.id % 7) end
local function best(a)
  local b, bf, bp
  for _, c in ipairs(CARDS) do
    local f = bestFinish(a, c.id)
    if f then local p = power(c, f); if not bp or p > bp then b, bf, bp = c, f, p end end
  end
  return b, bf, bp
end
local lastDuel = 0
function RG.ArcadeDuel()
  local a = store(); if not a then return end
  local mine, mf, mp = best(a)
  if not mine then return nil, "Open a pack first." end
  local now = GetTime and GetTime() or 0
  if lastDuel > 0 and now - lastDuel < 60 then return nil, "Your card is resting. Try again in a minute." end
  lastDuel = now
  local foe, ff = rollCard(), rollFinish()
  local BEATS = { [2] = 1, [1] = 3, [3] = 2, [4] = 2 }   -- NPC beats item, item beats place, place beats NPC
  local function score(c, f, o) local s = power(c, f) + math.random(0, 25); if BEATS[c.kind] == o.kind then s = s + 20 end; return s end
  local win = score(mine, mf, foe) >= score(foe, ff, mine)
  if win then a.coins = a.coins + 6; a.wins = (a.wins or 0) + 1 else a.losses = (a.losses or 0) + 1 end
  return win, mine, foe, mf, ff
end

function RG.ArcadeStats()
  local a = store() or { coins = 0, cards = {} }
  local own, prints = 0, 0
  for _, c in ipairs(CARDS) do
    if bestFinish(a, c.id) then own = own + 1 end
    for k = 1, 4 do if ((a.cards[c.name] or {})[k] or 0) > 0 then prints = prints + 1 end end
  end
  return a, own, #CARDS, prints
end

-- ---------------------------------------------------------------------------
-- Card widgets
-- ---------------------------------------------------------------------------
local function iconFor(c)
  if c.icon then return c.icon end
  if c.kind == 1 then
    local ic
    if C_Item and C_Item.GetItemIconByID then ic = C_Item.GetItemIconByID(c.ref) end
    if not ic and GetItemIcon then ic = GetItemIcon(c.ref) end
    return ic or "Interface\\Icons\\INV_Misc_QuestionMark"
  elseif c.kind == 2 then
    return "Interface\\Icons\\" .. (CREATURE_ICON[c.ref] or "INV_Misc_Head_Human_01")
  end
  return "Interface\\Icons\\" .. (c.text == "Zone" and "INV_Misc_Map_01" or "INV_Misc_Map02")
end

local holos = {}   -- visible holo/full-art widgets, animated together
local ticker = CreateFrame("Frame")
local clock = 0
ticker:SetScript("OnUpdate", function(_, dt)
  if not next(holos) then return end
  clock = clock + dt
  for w in pairs(holos) do
    if w:IsShown() then
      local h = (clock * 0.5 + w.phase) % 1
      local r, g, b = 0.5 + 0.5 * math.sin(h * 6.283), 0.5 + 0.5 * math.sin(h * 6.283 + 2.09), 0.5 + 0.5 * math.sin(h * 6.283 + 4.19)
      w.shine:SetVertexColor(r, g, b, w.finish == 4 and 0.28 or 0.38)
      w.edge:SetVertexColor(r, g, b, 1)
    else holos[w] = nil end
  end
end)

local function makeCard(parent, w, h)
  local f = CreateFrame("Frame", nil, parent, "BackdropTemplate")
  f:SetSize(w, h); f:EnableMouse(true); f.cw, f.ch = w, h
  RG.Round(f, 0.12, 0.12, 0.12, 1, 8)
  f.edge = f:CreateTexture(nil, "BORDER"); f.edge:SetPoint("TOPLEFT", -2, 2); f.edge:SetPoint("BOTTOMRIGHT", 2, -2); f.edge:SetColorTexture(1, 1, 1, 1)
  f.art = f:CreateTexture(nil, "ARTWORK"); f.art:SetTexCoord(0.07, 0.93, 0.07, 0.93)
  f.shine = f:CreateTexture(nil, "OVERLAY"); f.shine:SetPoint("TOPLEFT", 3, -3); f.shine:SetPoint("BOTTOMRIGHT", -3, 3); f.shine:SetColorTexture(1, 1, 1, 1); f.shine:SetBlendMode("ADD")
  f.bar = f:CreateTexture(nil, "OVERLAY", nil, 2); f.bar:SetPoint("BOTTOMLEFT", 3, 3); f.bar:SetPoint("BOTTOMRIGHT", -3, 3); f.bar:SetHeight(h * 0.3); f.bar:SetColorTexture(0, 0, 0, 0.7)
  f.name = RG.NewText(f, "GameFontHighlightSmall"); f.name:SetPoint("BOTTOM", 0, 6); f.name:SetWidth(w - 10); f.name:SetHeight(h * 0.26); f.name:SetJustifyV("MIDDLE")
  f.kind = RG.NewText(f, "GameFontNormalSmall"); f.kind:SetPoint("TOPLEFT", 6, -5)
  f.count = RG.NewText(f, "GameFontNormalSmall"); f.count:SetPoint("TOPRIGHT", -6, -5)
  f.phase = math.random()
  f:SetScript("OnEnter", function(self)
    local c = self.card
    if not c then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    if not self.known then GameTooltip:AddLine("Not found yet", 0.6, 0.6, 0.6)
    else
      local t = TIER[c.tier][3]
      GameTooltip:AddLine(c.name, t[1], t[2], t[3])
      GameTooltip:AddLine(KIND[c.kind] .. "  ·  " .. TIER[c.tier][1] .. "  ·  " .. FINISH[self.finish][1], 1, 1, 1)
      GameTooltip:AddLine(c.text, 0.75, 0.75, 0.75)
      GameTooltip:AddLine("Power " .. power(c, self.finish), 0.7, 0.9, 0.7)
      if self.copies and self.copies > 1 then GameTooltip:AddLine("You own " .. self.copies, 0.7, 0.7, 0.7) end
    end
    GameTooltip:Show()
  end)
  f:SetScript("OnLeave", function() GameTooltip:Hide() end)
  return f
end

-- card: the card; finish: 1-4 or nil (nothing owned); copies: how many you own
local function paint(w, card, finish, copies)
  w.card, w.known, w.finish, w.copies = card, finish ~= nil, finish or 1, copies
  holos[w] = nil
  if not card then w:Hide() return end
  w:Show()
  local t = TIER[card.tier][3]
  w.art:SetTexture(iconFor(card))
  w.art:ClearAllPoints()
  if not finish then
    w.edge:SetVertexColor(0.2, 0.2, 0.2, 1); w.shine:Hide(); w.art:SetDesaturated(true); w.art:SetVertexColor(0.25, 0.25, 0.25)
    w.art:SetPoint("TOP", 0, -(w.ch * 0.16)); w.art:SetSize(w.cw * 0.45, w.cw * 0.45)
    w.name:SetText("???"); w.name:SetTextColor(0.4, 0.4, 0.4); w.kind:SetText(""); w.count:SetText(""); w.bar:Show()
    return
  end
  w.art:SetDesaturated(false); w.art:SetVertexColor(1, 1, 1)
  w.name:SetText(card.name); w.name:SetTextColor(t[1], t[2], t[3])
  w.kind:SetText(KIND[card.kind]); w.kind:SetTextColor(0.7, 0.7, 0.7)
  w.count:SetText(copies and copies > 1 and ("x" .. copies) or "")
  if finish == 4 then   -- full art: the picture fills the card
    w.art:SetPoint("TOPLEFT", 3, -3); w.art:SetPoint("BOTTOMRIGHT", -3, 3)
    w.bar:Show(); w.shine:Show(); holos[w] = true
  else
    local s = math.min(w.cw * 0.5, w.ch * 0.42)
    w.art:SetPoint("TOP", 0, -(w.ch * 0.16)); w.art:SetSize(s, s)
    w.bar:Show()
    if finish == 3 then w.shine:Show(); holos[w] = true else w.shine:Hide() end
  end
  if finish == 1 then w.edge:SetVertexColor(0.45, 0.45, 0.45, 1)
  elseif finish == 2 then w.edge:SetVertexColor(1, 0.82, 0.25, 1) end
end

-- ---------------------------------------------------------------------------
-- Window
-- ---------------------------------------------------------------------------
local frame, cells, reveal
local COLS, ROWS, CW, CH = 6, 4, 104, 118
local view = { kind = 0, ownedOnly = false, page = 1 }

local function filtered(a)
  local list = {}
  for _, c in ipairs(CARDS) do
    if (view.kind == 0 or c.kind == view.kind) and (not view.ownedOnly or owned(a, c.id) > 0) then list[#list + 1] = c end
  end
  return list
end

local function showReveal(got)
  if not reveal then
    reveal = CreateFrame("Frame", "WaypathArcadePack", UIParent, "BackdropTemplate")
    reveal:SetSize(PACK_SIZE * 138 + 30, 230); reveal:SetPoint("CENTER", 0, 60); reveal:SetFrameStrata("FULLSCREEN_DIALOG")
    RG.DialogBackdrop(reveal)
    reveal.cards = {}
    for i = 1, PACK_SIZE do
      local c = makeCard(reveal, 128, 150); c:SetPoint("TOPLEFT", 14 + (i - 1) * 138, -18); reveal.cards[i] = c
      c.new = RG.NewText(c, "GameFontNormal"); c.new:SetPoint("BOTTOM", c, "TOP", 0, 2)
    end
    local ok = CreateFrame("Button", nil, reveal, "UIPanelButtonTemplate"); ok:SetSize(120, 24); ok:SetPoint("BOTTOM", 0, 14); ok:SetText("Nice"); ok:SetScript("OnClick", function() reveal:Hide() end)
    tinsert(UISpecialFrames, "WaypathArcadePack")
  end
  reveal:Show()
  for i = 1, PACK_SIZE do paint(reveal.cards[i], nil) end
  for i, g in ipairs(got) do
    local function show()
      if not reveal:IsShown() then return end
      local w = reveal.cards[i]
      paint(w, g.card, g.finish, 1)
      w.new:SetText(g.new and "|cff55ff55New!|r" or "")
    end
    if C_Timer and C_Timer.After then C_Timer.After((i - 1) * 0.45, show) else show() end
  end
end

local function build()
  frame = CreateFrame("Frame", "WaypathArcade", UIParent, "BackdropTemplate")
  frame:SetSize(COLS * CW + 44, ROWS * CH + 190); frame:SetPoint("CENTER"); frame:SetFrameStrata("DIALOG")
  frame:SetMovable(true); frame:EnableMouse(true); frame:RegisterForDrag("LeftButton")
  frame:SetScript("OnDragStart", frame.StartMoving); frame:SetScript("OnDragStop", frame.StopMovingOrSizing)
  RG.DialogBackdrop(frame)
  tinsert(UISpecialFrames, "WaypathArcade")
  frame.title = RG.NewText(frame, "GameFontNormalLarge"); frame.title:SetPoint("TOPLEFT", 22, -18); frame.title:SetText("Azeroth cards")
  frame.coins = RG.NewText(frame, "GameFontNormal"); frame.coins:SetPoint("TOPRIGHT", -44, -22)
  frame.sub = RG.NewText(frame, "GameFontHighlightSmall"); frame.sub:SetPoint("TOPLEFT", frame.title, "BOTTOMLEFT", 0, -6); frame.sub:SetTextColor(0.6, 0.6, 0.6)
  local close = CreateFrame("Button", nil, frame, "UIPanelCloseButton"); close:SetPoint("TOPRIGHT", -4, -4)

  -- filters
  frame.filters = {}
  local labels = { [0] = "All", "Items", "NPCs", "Places", "Legends" }
  for k = 0, 4 do
    local b = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate"); b:SetSize(70, 22); b:SetPoint("TOPLEFT", 22 + k * 74, -60); b:SetText(labels[k])
    b:SetScript("OnClick", function() view.kind = k; view.page = 1; RG.ArcadeRefresh(true) end)
    frame.filters[k] = b
  end
  frame.ownedBtn = CreateFrame("CheckButton", nil, frame, "UICheckButtonTemplate"); frame.ownedBtn:SetSize(24, 24); frame.ownedBtn:SetPoint("LEFT", frame.filters[4], "RIGHT", 14, 0)
  frame.ownedBtn.text = RG.NewText(frame.ownedBtn, "GameFontNormalSmall"); frame.ownedBtn.text:SetPoint("LEFT", frame.ownedBtn, "RIGHT", 2, 0); frame.ownedBtn.text:SetText("Owned only")
  frame.ownedBtn:SetScript("OnClick", function(self) view.ownedOnly = self:GetChecked(); view.page = 1; RG.ArcadeRefresh(true) end)

  cells = {}
  for i = 1, COLS * ROWS do
    local c = makeCard(frame, CW - 8, CH - 8)
    c:SetPoint("TOPLEFT", 26 + ((i - 1) % COLS) * CW, -92 - math.floor((i - 1) / COLS) * CH)
    cells[i] = c
  end

  local function btn(label, x, y, w, fn)
    local o = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate"); o:SetSize(w, 26); o:SetPoint("BOTTOM", x, y); o:SetText(label); o:SetScript("OnClick", fn)
    return o
  end
  frame.msg = RG.NewText(frame, "GameFontHighlight"); frame.msg:SetPoint("BOTTOM", 0, 82); frame.msg:SetWidth(COLS * CW - 20)
  frame.prev = btn("<", -60, 52, 40, function() view.page = view.page - 1; RG.ArcadeRefresh(true) end)
  frame.next = btn(">", 60, 52, 40, function() view.page = view.page + 1; RG.ArcadeRefresh(true) end)
  frame.pageText = RG.NewText(frame, "GameFontNormal"); frame.pageText:SetPoint("BOTTOM", 0, 58)
  frame.buy = btn("Open pack (" .. PACK_PRICE .. ")", -150, 16, 150, function()
    local got, err = RG.ArcadeOpenPack()
    if not got then frame.msg:SetText(err or "") return end
    showReveal(got); RG.ArcadeRefresh(true)
  end)
  frame.duel = btn("Duel for coins", 0, 16, 150, function()
    local win, mine, foe, mf, ff = RG.ArcadeDuel()
    if win == nil then frame.msg:SetText(mine or "") return end
    frame.msg:SetText((win and "Won! +6 coins. " or "Lost. ") .. mine.name .. " (" .. FINISH[mf][1] .. ") vs " .. foe.name .. " (" .. FINISH[ff][1] .. ")")
    RG.ArcadeRefresh(true)
  end)
  frame.sell = btn("Sell extras", 150, 16, 150, function()
    local n, coins = RG.ArcadeSellExtras()
    frame.msg:SetText(n > 0 and ("Sold " .. n .. " extra cards for " .. coins .. " coins. One of each print is kept.") or "No extras to sell: you keep one of each print.")
    RG.ArcadeRefresh(true)
  end)
end

function RG.ArcadeRefresh(keepMsg)
  if not (frame and frame:IsShown()) then return end
  local a, own, total, prints = RG.ArcadeStats()
  frame.coins:SetText("|cffffd100" .. (a.coins or 0) .. "|r coins")
  frame.sub:SetText(own .. " of " .. total .. " cards  ·  " .. prints .. " prints  ·  1 coin per 2% of a level  ·  " .. (a.wins or 0) .. " duel wins")
  if keepMsg ~= true then frame.msg:SetText("") end
  local list = filtered(a)
  local pages = math.max(1, math.ceil(#list / #cells))
  view.page = math.max(1, math.min(view.page, pages))
  for i, cell in ipairs(cells) do
    local c = list[(view.page - 1) * #cells + i]
    paint(cell, c, c and bestFinish(a, c.id), c and owned(a, c.id))
  end
  frame.pageText:SetText(view.page .. " / " .. pages)
  frame.prev:SetEnabled(view.page > 1); frame.next:SetEnabled(view.page < pages)
  frame.buy:SetEnabled((a.coins or 0) >= PACK_PRICE)
  for k, b in pairs(frame.filters) do b:SetEnabled(k ~= view.kind) end
end

function RG.ShowArcade()
  if not frame then build() end
  frame:Show(); RG.ArcadeRefresh()
end

local base = SlashCmdList.WAYPATH
SlashCmdList.WAYPATH = function(msg)
  local cmd = (msg or ""):match("^%s*(%S+)")
  cmd = cmd and cmd:lower()
  if cmd == "arcade" or cmd == "cards" then RG.ShowArcade() return end
  return base(msg)
end
